text(await tools.exec_command({cmd:"cat > tests/search-tracking.spec.ts <<'EOF'
import { gunzipSync } from "node:zlib";
import { expect, test } from "./backend";

test("each executed search emits one event and log, including typeahead, examples, Enter and retry", async ({
  backend,
  page,
}) => {
  const events: { event: string; properties: Record<string, unknown> }[] = [];
  const logs: unknown[] = [];
  await page.route("https://posthog.test/**", async (route) => {
    const request = route.request();
    const body = request.postDataBuffer();
    if (body) {
      const url = new URL(request.url());
      const decoded = body[0] === 0x1f && body[1] === 0x8b
        ? gunzipSync(body).toString()
        : url.searchParams.get("compression") === "base64"
          ? Buffer.from(new URLSearchParams(body.toString()).get("data")!, "base64").toString()
          : body.toString();
      const payload = JSON.parse(decoded);
      if (url.pathname === "/i/v1/logs") logs.push(payload);
      else if (url.pathname === "/e/") events.push(...(Array.isArray(payload) ? payload : [payload]));
    }
    await route.fulfill({ json: {} });
  });
  let fail = false;
  const searches: string[] = [];
  await backend.route("**/api/search?*", (route) => {
    searches.push(new URL(route.request().url()).searchParams.get("term")!);
    return fail
      ? route.fulfill({ status: 503, body: "service unavailable" })
      : route.fulfill({ json: { entities: [] } });
  });
  await page.goto("/search");
  const input = page.getByRole("searchbox");
  await input.fill("jo");
  await input.press("Enter");
  await input.fill("Canceled");
  await input.fill("");
  await input.fill("  Jo😀  ");
  await expect(page.getByRole("heading", { name: "No matches for “Jo😀”" })).toBeVisible();
  await expect.poll(() => events.filter(({ event }) => event === "search_submitted").length, { timeout: 10000 }).toBe(1);
  console.log("LOGS", JSON.stringify(logs));
  await page.getByRole("button", { name: "Clear search" }).click();
  await page.getByRole("button", { name: "John", exact: true }).click();
  await expect(page.getByRole("heading", { name: "No matches for “John”" })).toBeVisible();
  await input.fill("Enter");
  await input.press("Enter");
  await expect(page.getByRole("heading", { name: "No matches for “Enter”" })).toBeVisible();
  fail = true;
  await input.fill("Retry");
  await expect(page.getByRole("alert")).toBeVisible();
  fail = false;
  await page.getByRole("button", { name: "Try again" }).click();
  await expect(page.getByRole("heading", { name: "No matches for “Retry”" })).toBeVisible();
  await expect.poll(() => events.filter(({ event }) => event === "search_submitted").map(({ properties }) => properties.query_length), { timeout: 10000 }).toEqual([3, 4, 5, 5, 5]);
  expect(searches).toEqual(["Jo😀", "John", "Enter", "Retry", "Retry"]);
  console.log("FINAL LOGS", JSON.stringify(logs));
});
EOF
